package com.qfc.rag;
import com.baomidou.mybatisplus.annotation.*; import java.time.LocalDateTime;
@TableName("project_member") public class ProjectMember { @TableId(type=IdType.AUTO) private Long id; private Long projectId,userId; private String role,status; private LocalDateTime createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getProjectId(){return projectId;} public void setProjectId(Long v){projectId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
